import { chromium } from 'playwright';
const base=process.env.SUPABASE_URL,key=process.env.SUPABASE_PUBLISHABLE_KEY,runtime=process.env.RUNTIME_URL,run=process.env.GITHUB_RUN_ID;
async function req(url,opt={}){const r=await fetch(url,opt),t=await r.text();let b;try{b=JSON.parse(t)}catch{b={raw:t}}if(!r.ok)throw Error(r.status+' '+JSON.stringify(b));return b}
const signup=()=>req(base+'/auth/v1/signup',{method:'POST',headers:{apikey:key,'content-type':'application/json'},body:'{}'});const A=await signup(),B=await signup();if(!A.access_token||!B.access_token)throw Error('AUTH_BOOTSTRAP_FAILED');
const browser=await chromium.launch({headless:true});const origin=new URL(runtime).origin;const state=t=>({cookies:[],origins:[{origin,localStorage:[{name:'nayanet.supabase.auth',value:JSON.stringify(t)}]}]});const ac=await browser.newContext({storageState:state(A),viewport:{width:1440,height:1000}}),bc=await browser.newContext({storageState:state(B),viewport:{width:1440,height:1000}});const page=await ac.newPage(),bpage=await bc.newPage();
for(const [p,s] of [[page,'A'],[bpage,'B']]){await p.goto(runtime+'/?smart_lists_proof_'+s+'='+run,{waitUntil:'domcontentloaded',timeout:60000});await p.waitForTimeout(800);const a=await p.evaluate(async()=>window.NayaAssistantRuntime.init());if(!a.authenticated)throw Error('AUTH_HANDOFF_'+s)}
const space='04ee4dc8-bc73-47df-a1de-162570f6a56e';await page.evaluate(s=>window.NayaAssistantRuntime.joinSpace(s),space);await bpage.evaluate(s=>window.NayaAssistantRuntime.joinSpace(s),space);await page.evaluate(async({target,space})=>window.NayaAssistantRuntime.saveConnection(target,space),{target:B.user.id,space});const cs=await page.evaluate(async()=>window.NayaAssistantRuntime.listConnections());const cid=cs.find(x=>x.connected_member_id===B.user.id&&x.status==='active')?.id;if(!cid)throw Error('CONNECTION_SETUP_FAILED');
const name='Smart Lists human proof '+run;await page.evaluate(n=>{window.prompt=()=>n},name);await page.evaluate(()=>window.__nayaOpenSurface('lists'));await page.locator('.nc-modal').waitFor({state:'visible',timeout:15000});await page.locator('#nc-create').click();await page.waitForFunction(n=>[...document.querySelectorAll('.nc-card[data-list] b')].some(x=>x.textContent===n),name,{timeout:15000});let lid=await page.locator('.nc-card[data-list]').first().getAttribute('data-list');if(!lid)throw Error('CREATE_NOT_PROVEN');
await page.reload({waitUntil:'domcontentloaded',timeout:60000});await page.waitForTimeout(800);await page.evaluate(async()=>window.NayaAssistantRuntime.init());let ls=await page.evaluate(async()=>window.NayaAssistantRuntime.listSmartLists());if(!ls.some(x=>x.id===lid))throw Error('RELOAD_RETRIEVE_CREATE_NOT_PROVEN');
await page.evaluate(()=>window.__nayaOpenSurface('lists'));await page.locator('.nc-modal').waitFor({state:'visible',timeout:15000});let card=page.locator('.nc-card[data-list="'+lid+'"]');await card.locator('[data-add-select]').selectOption(cid);await card.locator('[data-add]').click();await page.waitForFunction(()=>document.querySelector('#nc-proof')?.textContent.includes('VERIFY MEMBERSHIP ✓'),{timeout:15000});
await page.reload({waitUntil:'domcontentloaded',timeout:60000});await page.waitForTimeout(800);await page.evaluate(async()=>window.NayaAssistantRuntime.init());ls=await page.evaluate(async()=>window.NayaAssistantRuntime.listSmartLists());let p=ls.find(x=>x.id===lid);if(!p?.members?.some(x=>x.connection_id===cid))throw Error('RELOAD_RETRIEVE_ADD_NOT_PROVEN');
await page.evaluate(()=>window.__nayaOpenSurface('lists'));await page.locator('.nc-modal').waitFor({state:'visible',timeout:15000});card=page.locator('.nc-card[data-list="'+lid+'"]');await card.locator('[data-remove]').click();await page.waitForFunction(()=>document.querySelector('#nc-proof')?.textContent.includes('VERIFY REMOVAL ✓'),{timeout:15000});
await page.reload({waitUntil:'domcontentloaded',timeout:60000});await page.waitForTimeout(800);await page.evaluate(async()=>window.NayaAssistantRuntime.init());ls=await page.evaluate(async()=>window.NayaAssistantRuntime.listSmartLists());p=ls.find(x=>x.id===lid);if(!p||p.members?.some(x=>x.connection_id===cid))throw Error('RELOAD_RETRIEVE_REMOVE_NOT_PROVEN');
const bls=await bpage.evaluate(async()=>window.NayaAssistantRuntime.listSmartLists());if(bls.some(x=>x.id===lid))throw Error('PRIVACY_LEAK');const u=await bpage.evaluate(async id=>{try{await window.NayaAssistantRuntime.addConnectionToList(id,crypto.randomUUID());return {blocked:false,error:'UNEXPECTED_SUCCESS'}}catch(e){return {blocked:true,error:String(e?.message||e)}}},lid);if(!u.blocked)throw Error('UNAUTHORIZED_WRITE_NOT_BLOCKED');console.log(JSON.stringify({status:'VERIFIED',run_id:run,runtime,list_id:lid,connection_id:cid,checks:['CREATE','RELOAD','RETRIEVE','ADD','RELOAD','VERIFY MEMBERSHIP','REMOVE','RELOAD','VERIFY REMOVAL','AUTHORIZATION BLOCKED','PRIVACY ISOLATED'],unauthorized:u}));await bc.close();await ac.close();await browser.close();